function fighter(id){return {id,x:id===0?122:358,y:FLOOR,vx:0,vy:0,face:id===0?1:-1,hp:100,stun:0,attack:0,attackType:'',attackHit:false,cool:0,block:false,jumps:0,walk:0,pose:0,energy:0,combo:0,comboTimer:0,flash:0}}
let p1=fighter(0),p2=fighter(1);
const palettes=[{skin:'#e6a47b',hair:'#251c36',cloth:'#247f94',trim:'#80eee0',pants:'#184b62',accent:'#47daca'},{skin:'#d89276',hair:'#30202c',cloth:'#bd365a',trim:'#ffb35e',pants:'#67304e',accent:'#ffcf69'}];
