const charSelect={player:0,cpu:1};
function selectNextPlayer(step){charSelect.player=(charSelect.player+step+featuredRoster.length)%featuredRoster.length;if(charSelect.player===charSelect.cpu)charSelect.cpu=(charSelect.cpu+step+featuredRoster.length)%featuredRoster.length}
